const ALLOWED_FIELDS = ['mode','runtime_location','terminal_code','package_structural_valid','package_fingerprint_problem','approval_not_expired','write_confirmed','business_confirmed','lock_acquired','already_consumed','authentication_success','member_command_found','get_member_found','member_exists_initial','new_member_success','assignment_success','assigned_field_count','expiry_date_assigned','member_exists_recheck','write_intent_recorded','consumed_marker_written','save_member_attempted','save_member_confirmed','save_outcome','readback_found','readback_match','masked_member_no','operation_id','source_record_id','source_fingerprint','error'];
const FORBIDDEN_FIELDS = ['member_payload','desired_business_fields','MemberNo','Name','EmailAddress','MobilePhone','DOB','member_no','name','email_address','dob','birthday','birthday_month','full_name','payload_hash','approval','password','server','database','user_id','sheet_id','sheet_url'];
const TERMINAL_CODES = ['DRY_RUN_VALIDATED','BLOCKED_MEMBER_EXISTS','APPROVAL_INVALID','SOURCE_FINGERPRINT_MISMATCH','CREATED_VERIFIED','CREATED_READBACK_MISMATCH','FAILED_BEFORE_WRITE','WRITE_OUTCOME_UNCERTAIN','OPERATOR_CONFIG_REQUIRED','WRITE_NOT_CONFIRMED','APPROVAL_REJECTED','APPROVAL_ON_HOLD','APPROVAL_ALREADY_CONSUMED','PACKAGE_ALREADY_CONSUMED','EXECUTION_LOCKED'];
const OP_RE = /^mcuat_[0-9a-f]{32}$/;
const SRID_RE = /^srcrec_[0-9a-f]{64}$/;
const FP_RE = /^fp_[0-9a-f]{64}$/;
const MASK_RE = /^(\*\*\*|.{2}\*\*\*.)$/;

const items = $input.all();
if (items.length !== 1) throw new Error('create_uat_expected_one_extracted_text_item');
const text = items[0].json.data;
if (typeof text !== 'string' || !text.trim()) throw new Error('create_uat_result_empty');
let result;
try { result = JSON.parse(text); } catch (e) { throw new Error('create_uat_result_malformed_json'); }
if (!result || typeof result !== 'object' || Array.isArray(result)) throw new Error('create_uat_result_not_a_single_object');
const keys = Object.keys(result);
if (keys.some((k) => FORBIDDEN_FIELDS.includes(k))) throw new Error('create_uat_result_forbidden_field_present');
for (const req of ['terminal_code','operation_id','source_record_id','source_fingerprint']) { if (!keys.includes(req)) throw new Error('create_uat_result_required_field_missing'); }
if (keys.some((k) => !ALLOWED_FIELDS.includes(k))) throw new Error('create_uat_result_unexpected_field_present');
if (!TERMINAL_CODES.includes(result.terminal_code)) throw new Error('create_uat_terminal_code_unrecognised');
if (!OP_RE.test(result.operation_id)) throw new Error('create_uat_operation_id_invalid');
if (!SRID_RE.test(result.source_record_id)) throw new Error('create_uat_source_record_id_invalid');
if (!FP_RE.test(result.source_fingerprint)) throw new Error('create_uat_source_fingerprint_invalid');
if (result.masked_member_no !== null && result.masked_member_no !== undefined && !MASK_RE.test(String(result.masked_member_no))) throw new Error('create_uat_masked_member_no_malformed');
return [{ json: result }];

const REQUIRED_EXPECTED_COLUMNS = ['uat_create_source_record_id','uat_create_source_fingerprint'];
const REQUIRED_REVIEW_COLUMNS = ['uat_create_operation_id','uat_create_terminal_code','uat_create_save_outcome','uat_create_reviewer_status'];
const result = $('Validate Sanitized Terminal Result Strictly').first().json;
const items = $input.all();
if (items.length !== 1) throw new Error('create_uat_requires_exactly_one_approved_source_row');
const row = items[0].json;
for (const c of REQUIRED_EXPECTED_COLUMNS.concat(REQUIRED_REVIEW_COLUMNS)) {
  if (!Object.prototype.hasOwnProperty.call(row, c)) throw new Error('create_uat_required_column_missing_add_columns_before_run');
}
const cell = (name) => String(row[name] ?? '').trim();

// Identity and fingerprint revalidation by hash comparison only (no raw PII in this
// workflow). A row number is never used as identity. Source drift (a different
// fingerprint recorded on the row) is rejected before any update.
if (cell('uat_create_source_record_id') !== result.source_record_id) throw new Error('create_uat_source_record_id_mismatch');
if (cell('uat_create_source_fingerprint') !== result.source_fingerprint) throw new Error('create_uat_source_fingerprint_mismatch');

const saveOutcome = String(result.save_outcome ?? '');
const wouldWrite = {
  uat_create_operation_id: result.operation_id,
  uat_create_terminal_code: result.terminal_code,
  uat_create_save_outcome: saveOutcome,
  uat_create_reviewer_status: 'UNREVIEWED'
};

// Idempotency: fully blank review cells -> apply once; exact prior values -> already_applied;
// anything else is a conflict and is refused (never a second differing write).
const blank = REQUIRED_REVIEW_COLUMNS.every((c) => cell(c) === '');
const exact = REQUIRED_REVIEW_COLUMNS.every((c) => cell(c) === String(wouldWrite[c]).trim());
let decision;
if (blank) decision = 'apply';
else if (exact) decision = 'already_applied';
else throw new Error('create_uat_conflicting_prior_mapping_refused');

return [{ json: {
  create_uat_decision: decision,
  uat_create_operation_id: wouldWrite.uat_create_operation_id,
  uat_create_terminal_code: wouldWrite.uat_create_terminal_code,
  uat_create_save_outcome: wouldWrite.uat_create_save_outcome,
  uat_create_reviewer_status: wouldWrite.uat_create_reviewer_status
} }];
